fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    str1
        .iter()
        .map(|&c| {
            if c.is_ascii_lowercase() {
                c.to_ascii_uppercase()
            } else {
                c
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let v: Vec<char> = Vec::new();
        let res = to_uppercase(&v);
        assert!(res.is_empty());
    }

    #[test]
    fn test_all_lowercase() {
        let v: Vec<char> = "abcdefghijklmnopqrstuvwxyz".chars().collect();
        let res = to_uppercase(&v);
        let expected: Vec<char> = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect();
        assert_eq!(res, expected);
    }

    #[test]
    fn test_mixed_ascii() {
        let v: Vec<char> = "Hello, World! 123".chars().collect();
        let res = to_uppercase(&v);
        let expected: Vec<char> = "HELLO, WORLD! 123".chars().collect();
        assert_eq!(res, expected);
    }

    #[test]
    fn test_unicode_unchanged() {
        let v: Vec<char> = vec!['ä', 'ß', 'Ω', 'δ', '中', '文'];
        let res = to_uppercase(&v);
        // to_ascii_uppercase doesn't affect these
        assert_eq!(res, v);
    }
}